from pathlib import Path
import re, sys
files = [Path('docs/reports/llm-wiki-strengthening-scorecard.md'), Path('wikis/marine-engineering/wiki/portal.md')]
pat = re.compile(r'\[[^\]]+\]\(([^)]+)\)')
missing=[]
for path in files:
    text=path.read_text()
    for m in pat.finditer(text):
        target=m.group(1).split('#',1)[0]
        if not target or re.match(r'^[a-z]+:', target) or target.startswith('mailto:'):
            continue
        if not (path.parent/target).resolve().exists():
            missing.append((str(path), target))
if missing:
    for item in missing:
        print('missing link:', item)
    sys.exit(1)
print('generated markdown local links passed')
