from pathlib import Path
import yaml
failures = []
for root in [Path('.claude/skills'), Path('.agents/skills')]:
    for path in root.rglob('SKILL.md'):
        text = path.read_text(errors='replace')
        if not text.startswith('---'):
            continue
        try:
            yaml.safe_load(text.split('---', 2)[1])
        except Exception as exc:
            failures.append((str(path), str(exc).splitlines()[0]))
if failures:
    for path, err in failures[:50]:
        print(f'FAIL {path}: {err}')
    print(f'{len(failures)} failure(s)')
    raise SystemExit(1)
print('OK all SKILL.md frontmatter parsed under .claude/skills and .agents/skills')
