from pathlib import Path
import yaml
failures = []
for root in [Path('.claude/skills'), Path('.agents/skills')]:
    for path in root.rglob('SKILL.md'):
        lines = path.read_text(errors='replace').splitlines()
        if not lines or lines[0] != '---':
            continue
        try:
            end = next(i for i, line in enumerate(lines[1:], start=1) if line == '---')
            yaml.safe_load('\n'.join(lines[1:end]))
        except Exception as exc:
            failures.append((str(path), str(exc).splitlines()[0]))
if failures:
    for path, err in failures[:50]:
        print(f'FAIL {path}: {err}')
    print(f'{len(failures)} failure(s)')
    raise SystemExit(1)
print('OK all line-delimited SKILL.md frontmatter parsed under .claude/skills and .agents/skills')
